1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HashSet;
7	import java.util.Set;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	
13	/**
14	 * Assigns the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'} where
15	 * {@code REGION} is the region derived from the owner (postcode first, then city; see
16	 * {@link Owner#getRegion()}) and {@code HASH8} is the first 8 upper-case hex characters
17	 * of {@code SHA-256(normalizedTelephone + lastName)} — the telephone in the E.164 form
18	 * already normalized by {@link ValidateOwnerFields}. There are no sequence numbers: the
19	 * code is a pure function of the owner's region and identity, so it is stable and needs
20	 * no per-city count.
21	 *
22	 * <p>Runs after {@link BuildOwner} and before {@link SaveOwner} in the
23	 * {@code POST /api/owners} pipeline; the code is persisted with the new owner and
24	 * returned by later reads. Because it shares {@link Owner#getRegion()} with the
25	 * {@code locality} field, the two always agree. It mutates the built {@link Owner} in
26	 * place (see {@code @Val} semantics).
27	 *
28	 * <p>Should the computed {@code '<REGION>-<HASH8>'} collide with an existing owner's
29	 * {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or
30	 * more that makes it unique; the de-duplicated code is what gets stored. The new owner
31	 * is not yet persisted here, so it is never compared against itself.
32	 */
33	public class AssignCustomerCode {
34	
35	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
36	        String hash8 = shaHex8(owner.getTelephone() + owner.getLastName());
37	        String base = owner.getRegion() + "-" + hash8;
38	
39	        Set<String> existingCodes = new HashSet<>();
40	        for (Owner existing : ownerRepository.findAll()) {
41	            existingCodes.add(existing.getCustomerCode());
42	        }
43	
44	        String code = base;
45	        for (int n = 2; existingCodes.contains(code); n++) {
46	            code = base + "-" + n;
47	        }
48	        owner.setCustomerCode(code);
49	    }
50	
51	    /** First 8 upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code value}. */
52	    private static String shaHex8(String value) {
53	        try {
54	            byte[] digest = MessageDigest.getInstance("SHA-256")
55	                .digest(value.getBytes(StandardCharsets.UTF_8));
56	            StringBuilder sb = new StringBuilder(8);
57	            for (int i = 0; i < 4; i++) {
58	                sb.append(String.format("%02X", digest[i]));
59	            }
60	            return sb.toString();
61	        }
62	        catch (NoSuchAlgorithmException e) {
63	            throw new IllegalStateException("SHA-256 not available", e);
64	        }
65	    }
66	}
