1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	
8	/**
9	 * Consolidated duplicate detection for create-owner: rejects a request whose whole derived
10	 * {@code identityKey} equals that of an existing owner, responding 409 via
11	 * {@link DuplicateIdentityException}.
12	 *
13	 * <p>The key (see {@link Owner#getIdentityKey()}) is the SHA-256 hex digest over
14	 * {@code normalizedTelephone|lowerEmail|soundex(lastName)}, so the former separate telephone,
15	 * email and household checks are now a single full-key comparison. Because the telephone is part
16	 * of the key, two owners with the same last name and postcode but different telephones have
17	 * different identity keys and are both allowed (the second is a soft match); only an exact
18	 * full-key match is a duplicate. The email-domain blocklist is applied earlier, during field
19	 * validation, so a blocked domain is a 400 before this check runs.
20	 *
21	 * <p>Runs after {@link AssignHousehold} and before {@link SaveOwner} persists anything. The new
22	 * owner is not yet in the repository, so it is never compared against itself; soft-deleted owners
23	 * are ignored.
24	 */
25	public class EnsureUniqueIdentity {
26	
27	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
28	            throws DuplicateIdentityException {
29	        String identityKey = owner.getIdentityKey();
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (existing.isDeleted()) {
32	                continue; // a soft-deleted owner no longer blocks a duplicate
33	            }
34	            if (identityKey.equals(existing.getIdentityKey())) {
35	                throw new DuplicateIdentityException(identityKey);
36	            }
37	        }
38	    }
39	}
