1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.slf4j.Logger;
4	import org.slf4j.LoggerFactory;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Emits audit output to the dedicated {@code AUDIT} logger on a successful create:
11	 * first the human-readable audit line — carrying the new owner's id,
12	 * {@code customerCode}, {@code registrationDate}, numeric {@code membershipLevel} and
13	 * the derived {@code membershipNumber} — then an immutable structured
14	 * {@link OwnerCreatedEvent} rendered as JSON.
15	 *
16	 * <p>Runs after {@link SaveOwner} (so the id is assigned) and before
17	 * {@link RespondWithOwnerCreated} in the {@code POST /api/owners} pipeline.
18	 */
19	public class AuditOwnerCreated {
20	
21	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
22	
23	    public void service(@Val Owner owner) {
24	        String membershipNumber = String.format("%s-M%s",
25	            owner.getCustomerCode(), owner.getFiscalYear().substring(2));
26	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
27	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
28	            owner.getMembershipLevel(), membershipNumber);
29	        // Structured, machine-readable companion to the line above. Passed as a single
30	        // argument so the JSON braces are never treated as SLF4J placeholders.
31	        AUDIT.info("{}", OwnerCreatedEvent.next(owner).toJson());
32	    }
33	}
