1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Immutable structured audit event for a successful owner create, emitted to the
9	 * {@code AUDIT} logger by {@link AuditOwnerCreated} alongside the human-readable audit
10	 * line. Serialized as the JSON object
11	 * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}}.
12	 *
13	 * <p>The {@code customerCode} slot carries the owner's <em>current primary
14	 * identifier</em> — sourced from {@link Owner#getPrimaryIdentifier()}, which is the
15	 * {@code customerCode} today and becomes the memberId once the two are unified. The
16	 * event therefore follows that change without edits here.
17	 *
18	 * <p>{@link #seq()} is a process-wide, monotonically increasing sequence stamped when
19	 * the event is built (see {@link #next(Owner)}); the record itself is immutable.
20	 */
21	public record OwnerCreatedEvent(long seq, int ownerId, String customerCode, int membershipLevel) {
22	
23	    /** The {@code event} marker carried by every instance. */
24	    public static final String EVENT = "OWNER_CREATED";
25	
26	    private static final AtomicLong SEQUENCE = new AtomicLong();
27	
28	    /**
29	     * Builds the next event for {@code owner}, stamping the next sequence number and
30	     * capturing the owner's current primary identifier and derived membership level.
31	     */
32	    public static OwnerCreatedEvent next(Owner owner) {
33	        return new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), owner.getId(),
34	            owner.getPrimaryIdentifier(), owner.getMembershipLevel());
35	    }
36	
37	    /** Compact JSON rendering with the fields in specification order. */
38	    public String toJson() {
39	        return String.format(
40	            "{\"seq\":%d,\"ownerId\":%d,\"customerCode\":%s,\"membershipLevel\":%d,\"event\":\"%s\"}",
41	            this.seq, this.ownerId, jsonString(this.customerCode), this.membershipLevel, EVENT);
42	    }
43	
44	    /** JSON string literal (with escaping) for {@code value}, or {@code null} when absent. */
45	    private static String jsonString(String value) {
46	        if (value == null) {
47	            return "null";
48	        }
49	        return '"' + value.replace("\\", "\\\\").replace("\"", "\\\"") + '"';
50	    }
51	}
