37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "title")
42	    private String title;
43	
44	    @Column(name = "address")
45	    @NotEmpty
46	    private String address;
47	
48	    @Column(name = "address_line1")
49	    private String addressLine1;
50	
51	    @Column(name = "address_line2")
52	    private String addressLine2;
53	
54	    @Column(name = "city")
55	    @NotEmpty
56	    private String city;
57	
58	    @Column(name = "telephone")
59	    @NotEmpty
60	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
61	    private String telephone;
62	
63	    @Column(name = "email")
64	    private String email;
65	
66	    @Column(name = "postcode")
67	    private String postcode;
68	
69	    @Column(name = "registration_date")
70	    private LocalDate registrationDate;
71	
72	    @Column(name = "birth_date")
73	    private LocalDate birthDate;
74	
75	    @Column(name = "customer_code")
76	    private String customerCode;
77	
78	    @Column(name = "household_id")
79	    private String householdId;
80	
81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    @Column(name = "household_member_count")
85	    private Integer householdMemberCount;
86	
87	    @Column(name = "membership_level_cap")
88	    private Integer membershipLevelCap;
89	
90	    @Column(name = "possible_duplicate")
91	    private boolean possibleDuplicate;
92	
93	    @Column(name = "possible_duplicate_of")
94	    private Integer possibleDuplicateOf;
95	
96	    @Column(name = "deleted")
97	    private boolean deleted;
98	
99	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
100	    private Set<Pet> pets;
101	
102	    public String getTitle() {
103	        return this.title;
104	    }
105	
106	    public void setTitle(String title) {
107	        this.title = title;
108	    }
109	
110	    /**
111	     * The owner's salutation: the supplied {@code title} (MR/MRS/MS/DR) followed by a
112	     * single space and the {@code lastName}, or just the {@code lastName} when no title
113	     * was given.
114	     */
115	    @Transient
116	    public String getSalutation() {
117	        if (this.title == null || this.title.isBlank()) {
118	            return getLastName();
119	        }
120	        return this.title + " " + getLastName();
121	    }
122	
123	    public String getAddress() {
124	        return this.address;
125	    }
126	
127	    public void setAddress(String address) {
128	        this.address = address;
129	    }
130	
131	    public String getAddressLine1() {
132	        return this.addressLine1;
133	    }
134	
135	    public void setAddressLine1(String addressLine1) {
136	        this.addressLine1 = addressLine1;
137	    }
138	
139	    public String getAddressLine2() {
140	        return this.addressLine2;
141	    }
142	
143	    public void setAddressLine2(String addressLine2) {
144	        this.addressLine2 = addressLine2;
145	    }
146	
147	    public String getCity() {
148	        return this.city;
149	    }
150	
151	    public void setCity(String city) {
152	        this.city = city;
153	    }
154	
155	    public String getTelephone() {
156	        return this.telephone;
157	    }
158	
159	    public void setTelephone(String telephone) {
160	        this.telephone = telephone;
161	    }
162	
163	    public String getEmail() {
164	        return this.email;
165	    }
166	
167	    public void setEmail(String email) {
168	        this.email = email;
169	    }
170	
171	    public String getPostcode() {
172	        return this.postcode;
173	    }
174	
175	    public void setPostcode(String postcode) {
176	        this.postcode = postcode;
177	    }
178	
179	    public LocalDate getRegistrationDate() {
180	        return this.registrationDate;
181	    }
182	
183	    public void setRegistrationDate(LocalDate registrationDate) {
184	        this.registrationDate = registrationDate;
185	    }
186	
187	    public LocalDate getBirthDate() {
188	        return this.birthDate;
189	    }
190	
191	    public void setBirthDate(LocalDate birthDate) {
192	        this.birthDate = birthDate;
193	    }
194	
195	    /**
196	     * The owner's age band, derived from {@code birthDate} measured against
197	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to
198	     * 64, and {@code SENIOR} at 65 or over. Returns {@code null} when no birth date was
199	     * supplied, so the field is absent from the response.
200	     */
201	    @Transient
202	    public String getAgeBand() {
203	        if (this.birthDate == null || this.registrationDate == null) {
204	            return null;
205	        }
206	        int years = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
207	        if (years < 18) {
208	            return "MINOR";
209	        }
210	        if (years < 65) {
211	            return "ADULT";
212	        }
213	        return "SENIOR";
214	    }
215	
216	    public String getCustomerCode() {
217	        return this.customerCode;
218	    }
219	
220	    public void setCustomerCode(String customerCode) {
221	        this.customerCode = customerCode;
222	    }
223	
224	    /**
225	     * The owner's current primary identifier. Today this is the
226	     * {@link #getCustomerCode() customerCode}; when the customer code is unified into
227	     * the memberId, this single accessor returns the memberId instead, and every
228	     * consumer that carries the primary identifier — notably the {@code OWNER_CREATED}
229	     * audit event — follows without further change.
230	     */
231	    @Transient
232	    public String getPrimaryIdentifier() {
233	        return getCustomerCode();
234	    }
235	
236	    public String getHouseholdId() {
237	        return this.householdId;
238	    }
239	
240	    public void setHouseholdId(String householdId) {
241	        this.householdId = householdId;
242	    }
243	
244	    public Integer getNamesakeCount() {
245	        return this.namesakeCount;
246	    }
247	
248	    public void setNamesakeCount(Integer namesakeCount) {
249	        this.namesakeCount = namesakeCount;
250	    }
251	
252	    public Integer getHouseholdMemberCount() {
253	        return this.householdMemberCount;
254	    }
255	
256	    public void setHouseholdMemberCount(Integer householdMemberCount) {
257	        this.householdMemberCount = householdMemberCount;
258	    }
259	
260	    public Integer getMembershipLevelCap() {
261	        return this.membershipLevelCap;
262	    }
263	
264	    public void setMembershipLevelCap(Integer membershipLevelCap) {
265	        this.membershipLevelCap = membershipLevelCap;
266	    }
267	
268	    public boolean isPossibleDuplicate() {
269	        return this.possibleDuplicate;
270	    }
271	
272	    public void setPossibleDuplicate(boolean possibleDuplicate) {
273	        this.possibleDuplicate = possibleDuplicate;
274	    }
275	
276	    public Integer getPossibleDuplicateOf() {
277	        return this.possibleDuplicateOf;
278	    }
279	
280	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
281	        this.possibleDuplicateOf = possibleDuplicateOf;
282	    }
283	
284	    /**
285	     * Whether this owner has been soft-deleted. A newly created owner is not deleted;
286	     * {@code DELETE /api/owners/{id}} sets this true while retaining the row, and the
287	     * create-owner duplicate/identity checks ignore owners flagged deleted.
288	     */
289	    public boolean isDeleted() {
290	        return this.deleted;
291	    }
292	
293	    public void setDeleted(boolean deleted) {
294	        this.deleted = deleted;
295	    }
296	
297	    /**
298	     * The owner's membership points, accumulated from four factors: start at 0, add 2
299	     * when an email is present, add 1 when {@code namesakeCount} is 0, add 2 for a
300	     * household of 3 or more members, and add 3 when the owner's tenure spans at least
301	     * one elapsed fiscal year. The tenure points are the only route to 6 or more:
302	     * because a newly created owner has zero elapsed fiscal years of tenure, a new owner
303	     * scores at most 5 points (2 email + 1 namesake + 2 household).
304	     */
305	    @Transient
306	    public int getMembershipPoints() {
307	        int points = 0;
308	        if (this.email != null && !this.email.isBlank()) {
309	            points += 2;
310	        }
311	        if (this.namesakeCount != null && this.namesakeCount == 0) {
312	            points += 1;
313	        }
314	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
315	            points += 2;
316	        }
317	        if (getTenureFiscalYears() >= 1) {
318	            points += 3;
319	        }
320	        return points;
321	    }
322	
323	    /**
324	     * The owner's numeric membership level, derived from {@link #getMembershipPoints()}:
325	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Because a newly
326	     * created owner scores at most 5 points (tenure being the only route to 6), a new
327	     * owner never exceeds level 3.
328	     *
329	     * <p>The result is then bounded by {@code membershipLevelCap} when one is set: a new
330	     * owner's level cannot exceed one above the highest level among the existing members
331	     * of their household, so the reported level is the lesser of the points-derived level
332	     * and that cap.
333	     */
334	    @Transient
335	    public int getMembershipLevel() {
336	        int level = pointsLevel();
337	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
338	            return this.membershipLevelCap;
339	        }
340	        return level;
341	    }
342	
343	    /** The uncapped, points-derived membership level (see {@link #getMembershipLevel()}). */
344	    private int pointsLevel() {
345	        int points = getMembershipPoints();
346	        if (points <= 1) {
347	            return 1;
348	        }
349	        if (points <= 3) {
350	            return 2;
351	        }
352	        if (points <= 5) {
353	            return 3;
354	        }
355	        return 4;
356	    }
357	
358	    /**
359	     * The owner's tenure counted in elapsed fiscal years: the number of fiscal-year
360	     * boundaries (each 1 July) crossed between {@code registrationDate} and today, i.e.
361	     * {@code fiscalYearOf(today) - fiscalYearOf(registrationDate)}. Zero when no
362	     * registration date is set, and zero for an owner registered in the current fiscal
363	     * year, so the tenure point of {@link #getMembershipLevel()} is never earned at
364	     * creation.
365	     */
366	    @Transient
367	    public long getTenureFiscalYears() {
368	        if (this.registrationDate == null) {
369	            return 0;
370	        }
371	        return (long) fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate);
372	    }
373	
374	    /**
375	     * The owner's fiscal year, formatted {@code 'FY<YY>'}, derived from the
376	     * business-day-adjusted {@code registrationDate}. The fiscal year starts on 1 July,
377	     * so a date in July or later belongs to the fiscal year named by its own calendar
378	     * year, and a date in January to June belongs to the fiscal year that started the
379	     * previous 1 July. {@code YY} is the last two digits of that fiscal year. Returns
380	     * {@code null} when no registration date is set.
381	     */
382	    @Transient
383	    public String getFiscalYear() {
384	        if (this.registrationDate == null) {
385	            return null;
386	        }
387	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
388	    }
389	
390	    /**
391	     * The fiscal year (named by the calendar year in which its 1 July start falls) that
392	     * {@code date} belongs to. July onward is the current calendar year; January to June
393	     * belongs to the fiscal year that began the previous 1 July.
394	     */
395	    private static int fiscalYearOf(LocalDate date) {
396	        return date.getMonthValue() >= java.time.Month.JULY.getValue()
397	                ? date.getYear() : date.getYear() - 1;
398	    }
399	
400	    /**
401	     * The owner's canonical region, preferring the postcode over the city.
402	     *
403	     * <p>The 4-digit postcode range is consulted first (NSW 2000-2099, VIC 3000-3099,
404	     * QLD 4000-4099); only when the postcode is absent or in no known range does this
405	     * fall back to the fixed city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC,
406	     * Brisbane-&gt;QLD). Anything unresolved is {@code "UNKNOWN"}. This single derivation
407	     * backs both the {@code locality} field and the {@code REGION} segment of the
408	     * {@code customerCode}, so the two always agree.
409	     */
410	    @Transient
411	    public String getRegion() {
412	        if (this.postcode != null && this.postcode.matches("[0-9]{4}")) {
413	            int value = Integer.parseInt(this.postcode);
414	            if (value >= 2000 && value <= 2099) {
415	                return "NSW";
416	            }
417	            if (value >= 3000 && value <= 3099) {
418	                return "VIC";
419	            }
420	            if (value >= 4000 && value <= 4099) {
421	                return "QLD";
422	            }
423	        }
424	        if ("Sydney".equals(this.city)) {
425	            return "NSW";
426	        }
427	        if ("Melbourne".equals(this.city)) {
428	            return "VIC";
429	        }
430	        if ("Brisbane".equals(this.city)) {
431	            return "QLD";
432	        }
433	        return "UNKNOWN";
434	    }
435	
436	    /**
437	     * The owner's segment, formatted {@code '<TIER>_<AREA>'} — one of
438	     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
439	     * {@code STANDARD_REGIONAL}. The {@code TIER} is {@code PREMIUM} when
440	     * {@link #getMembershipLevel()} is 3 or more, otherwise {@code STANDARD}. The
441	     * {@code AREA} is {@code METRO} when {@link #getRegion()} is a known region (NSW, VIC
442	     * or QLD), otherwise {@code REGIONAL}.
443	     */
444	    @Transient
445	    public String getOwnerSegment() {
446	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
447	        String area = "UNKNOWN".equals(getRegion()) ? "REGIONAL" : "METRO";
448	        return tier + "_" + area;
449	    }
450	
451	    /**
452	     * The owner's IANA timezone, derived from {@link #getRegion()} via the fixed
