3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns the owner's deterministic {@code householdId}: the first 12 hex characters of
12	 * SHA-256 over {@code normalizedLastName + '|' + postcode}. Because the value is derived
13	 * purely from the (last name, postcode) pair, every owner sharing that pair computes the
14	 * same identifier automatically — the household is keyed on the pair, not created by an
15	 * explicit opt-in.
16	 *
17	 * <p>The last name is normalized (compared case-insensitively with collapsed whitespace)
18	 * before hashing; the postcode is used verbatim, treated as empty when absent. So two
19	 * owners with the same last name and postcode always share a household, regardless of
20	 * creation order or the {@code sharesHousehold} flag.
21	 *
22	 * <p>Runs after {@link BuildOwner} (which produces the {@link Owner}) and before
23	 * {@link EnsureUniqueIdentity}/{@link SaveOwner}; it mutates the built owner in place
24	 * (see {@code @Val} semantics). The computed id feeds the household-size count and
25	 * membership derivations; it is no longer part of the {@code identityKey}.
26	 */
27	public class AssignHousehold {
28	
29	    public void service(@Val Owner owner) {
30	        String lastName = normalize(owner.getLastName());
31	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
32	        owner.setHouseholdId(householdId(lastName, postcode));
33	    }
34	
35	    /** Deterministic 12-char hex id over the normalized last name and postcode. */
36	    private static String householdId(String lastName, String postcode) {
37	        return sha256hex(lastName + "|" + postcode).substring(0, 12);
38	    }
39	
40	    private static String sha256hex(String value) {
41	        try {
42	            byte[] digest = MessageDigest.getInstance("SHA-256")
43	                    .digest(value.getBytes(StandardCharsets.UTF_8));
44	            StringBuilder sb = new StringBuilder(digest.length * 2);
45	            for (byte b : digest) {
46	                sb.append(String.format("%02x", b));
47	            }
48	            return sb.toString();
49	        }
50	        catch (NoSuchAlgorithmException e) {
51	            throw new IllegalStateException(e);
52	        }
53	    }
54	
55	    /** Lower-cases and collapses runs of whitespace to a single space, trimming the ends. */
56	    private static String normalize(String value) {
57	        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase();
58	    }
59	}
