3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.model.Soundex;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	
9	/**
10	 * Flags a soft (non-hard) duplicate on the owner being created.
11	 *
12	 * <p>A hard duplicate — an existing owner with the same whole {@code identityKey} — has
13	 * already been rejected with 409 by {@link EnsureUniqueIdentity}. The soft-match key is
14	 * a phonetic near-match: the last names share a {@link Soundex} code and the postcodes
15	 * match, while the whole {@code identityKey} differs (so it is not a hard duplicate).
16	 * Because the telephone is part of the identity key, two owners with the same last name
17	 * and postcode but different telephones reach this step and are flagged here rather than
18	 * rejected.
19	 *
20	 * <p>A <em>declared</em> household member ({@code sharesHousehold: true}) is not a
21	 * suspected duplicate, so it is never flagged. For any other owner the soft match, when
22	 * present, sets {@code possibleDuplicate} true and {@code possibleDuplicateOf} to the
23	 * matching owner's id (the lowest id when several match, for determinism); otherwise
24	 * {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is absent.
25	 *
26	 * <p>Runs after {@link EnsureUniqueIdentity} and before {@link SaveOwner} in the
27	 * {@code POST /api/owners} pipeline, so the new owner is not yet persisted and is never
28	 * compared against itself; the flags are persisted with the new owner and returned by
29	 * later reads. It mutates the built {@link Owner} in place (see {@code @Val} semantics).
30	 */
31	public class AssignPossibleDuplicate {
32	
33	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
34	            OwnerRepository ownerRepository) {
35	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
36	            return; // a declared household member is not a suspected duplicate
37	        }
38	        String postcode = owner.getPostcode();
39	        if (postcode == null) {
40	            return;
41	        }
42	        String lastNameCode = Soundex.encode(owner.getLastName());
43	        String identityKey = owner.getIdentityKey();
44	        Owner match = null;
45	        for (Owner existing : ownerRepository.findAll()) {
46	            if (existing.isDeleted()) {
47	                continue; // a soft-deleted owner is not a possible-duplicate match
48	            }
49	            if (lastNameCode.equals(Soundex.encode(existing.getLastName()))
50	                    && postcode.equals(existing.getPostcode())
51	                    && !identityKey.equals(existing.getIdentityKey())
52	                    && (match == null || existing.getId() < match.getId())) {
53	                match = existing;
54	            }
55	        }
56	        if (match != null) {
57	            owner.setPossibleDuplicate(true);
58	            owner.setPossibleDuplicateOf(match.getId());
59	        }
60	    }
61	}
