3	/**
4	 * American Soundex phonetic encoding: the retained first letter of a name followed by three
5	 * digits derived from its remaining consonants, so names that sound alike share a code (for
6	 * example {@code "Robert"} and {@code "Rupert"} both encode to {@code "R163"}).
7	 *
8	 * <p>The encoding maps consonants to digits ({@code b,f,p,v}&rarr;1; {@code c,g,j,k,q,s,x,z}&rarr;2;
9	 * {@code d,t}&rarr;3; {@code l}&rarr;4; {@code m,n}&rarr;5; {@code r}&rarr;6), drops vowels, and
10	 * collapses runs of the same code (adjacent, or separated only by {@code h}/{@code w}) to a single
11	 * digit; a vowel between two same-coded consonants keeps both. The result is padded with zeros or
12	 * truncated to exactly four characters. A {@code null}, blank or letterless value encodes to the
13	 * empty string.
14	 *
15	 * <p>Used by {@link Owner#getIdentityKey()} (the last-name component of the duplicate-detection
16	 * key) and by the create-owner soft-match, which flags a possible duplicate when the last names
17	 * share a Soundex code and the postcodes match.
18	 */
19	public final class Soundex {
20	
21	    /** Soundex digit for each letter A-Z; {@code '0'} means the letter is not coded. */
22	    private static final String MAPPING = "01230120022455012623010202";
23	
24	    private Soundex() {
25	    }
26	
27	    /** The four-character American Soundex code of {@code value}, or {@code ""} when it has no letters. */
28	    public static String encode(String value) {
29	        if (value == null) {
30	            return "";
31	        }
32	        StringBuilder letters = new StringBuilder();
33	        for (int i = 0; i < value.length(); i++) {
34	            char c = value.charAt(i);
35	            if (Character.isLetter(c)) {
36	                letters.append(Character.toUpperCase(c));
37	            }
38	        }
39	        if (letters.length() == 0) {
40	            return "";
41	        }
42	        StringBuilder code = new StringBuilder();
43	        char first = letters.charAt(0);
44	        code.append(first);
45	        char lastCode = codeOf(first);
46	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
47	            char c = letters.charAt(i);
48	            if (c == 'H' || c == 'W') {
49	                continue; // transparent: does not break a run of the same code
50	            }
51	            char digit = codeOf(c);
52	            if (digit != '0' && digit != lastCode) {
53	                code.append(digit);
54	            }
55	            // A vowel resets the run so a following same-coded consonant is coded again;
56	            // a coded consonant carries its digit forward to collapse an adjacent repeat.
57	            lastCode = digit;
58	        }
59	        while (code.length() < 4) {
60	            code.append('0');
61	        }
62	        return code.toString();
63	    }
64	
65	    /** The Soundex digit for a single upper-case letter, or {@code '0'} when it is not coded. */
66	    private static char codeOf(char letter) {
67	        int index = letter - 'A';
68	        if (index < 0 || index >= MAPPING.length()) {
69	            return '0';
70	        }
71	        return MAPPING.charAt(index);
72	    }
73	}
