3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
10	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
11	import org.springframework.web.bind.annotation.RequestBody;
12	
13	/**
14	 * Rejects a create-owner request that is missing or blank in any required field
15	 * ({@code firstName}, {@code lastName}, address, {@code city}, {@code telephone}).
16	 *
17	 * <p>The address may be supplied in either form: the structured {@code addressLine1}
18	 * (with optional {@code addressLine2}) is preferred when a non-blank {@code addressLine1}
19	 * is given, otherwise the flat {@code address} is used — an owner is valid when it carries
20	 * an address in either form. The supplied lines are normalized (see
21	 * {@link AddressNormalizer}) and the composed, normalized {@code address} is stored back
22	 * (structured {@code addressLine1} plus a single space and {@code addressLine2} when
23	 * present); the flat form is kept accepted for backward compatibility.
24	 *
25	 * <p>Runs first in the {@code POST /api/owners} pipeline and binds the body without
26	 * {@code @Valid}, so a missing field surfaces as a {@link MissingOwnerFieldsException}
27	 * (400 with an {@code errors} array) rather than the generic schema-validation response.
28	 * The address is normalized first so the blank check rejects one that is empty after
29	 * normalization. It then normalizes the
30	 * telephone to E.164 form (see {@link TelephoneE164}), rejecting with an
31	 * {@link InvalidTelephoneException} (400) when it cannot form a valid E.164 number.
32	 * On success it stores the normalized address and E.164 telephone and republishes the
33	 * body for {@link BuildOwner}.
34	 */
35	public class ValidateOwnerFields {
36	
37	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
38	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
39	        List<String> errors = new ArrayList<>();
40	        // Normalize whichever address fields were supplied. The structured lines are
41	        // preferred; the flat 'address' remains accepted for backward compatibility.
42	        String line1 = AddressNormalizer.normalize(request.getAddressLine1());
43	        String line2 = AddressNormalizer.normalize(request.getAddressLine2());
44	        String flat = AddressNormalizer.normalize(request.getAddress());
45	        boolean hasStructured = !isBlank(line1);
46	        String address = hasStructured ? AddressNormalizer.compose(line1, line2) : flat;
47	        if (isBlank(request.getFirstName())) {
48	            errors.add("firstName");
49	        }
50	        if (isBlank(request.getLastName())) {
51	            errors.add("lastName");
52	        }
53	        // Valid with an address in EITHER form: a non-blank addressLine1 or flat address.
54	        if (isBlank(address)) {
55	            errors.add("address");
56	        }
57	        if (isBlank(request.getCity())) {
58	            errors.add("city");
59	        }
60	        if (isBlank(request.getTelephone())) {
61	            errors.add("telephone");
62	        }
63	        if (!errors.isEmpty()) {
64	            throw new MissingOwnerFieldsException(errors);
65	        }
66	        request.setAddressLine1(hasStructured ? line1 : null);
67	        request.setAddressLine2(hasStructured && !isBlank(line2) ? line2 : null);
68	        request.setAddress(address);
69	        String telephone = TelephoneE164.normalize(request.getTelephone());
70	        if (telephone == null) {
71	            throw new InvalidTelephoneException(
72	                    "Telephone cannot be normalized to a valid E.164 number");
73	        }
74	        request.setTelephone(telephone);
75	        request.setEmail(OwnerEmail.normalize(request.getEmail()));
76	        validated.set(request);
77	    }
78	
79	    private static boolean isBlank(String value) {
80	        return value == null || value.isBlank();
81	    }
82	}
