11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "selfLink",
22	        expression = "java(\"/api/owners/\" + owner.getId())")
23	    @Mapping(target = "displayName",
24	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
25	    @Mapping(target = "initials",
26	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
27	    @Mapping(target = "membershipNumber",
28	        expression = "java(String.format(\"%s-M%s\", owner.getCustomerCode(), owner.getFiscalYear().substring(2)))")
29	    @Mapping(target = "fiscalYear",
30	        expression = "java(owner.getFiscalYear())")
31	    @Mapping(target = "locality",
32	        expression = "java(owner.getRegion())")
33	    @Mapping(target = "timezone",
34	        expression = "java(owner.getTimezone())")
35	    @Mapping(target = "checkDigit",
36	        expression = "java(luhn(owner.getCustomerCode()))")
37	    @Mapping(target = "telephoneDisplay",
38	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.TelephoneE164.display(owner.getTelephone()))")
39	    @Mapping(target = "bulkSignupWarning", ignore = true)
40	    OwnerDto toOwnerDto(Owner owner);
41	
42	    /**
43	     * The single Luhn check digit (0-9) computed over the decimal digits contained in
44	     * {@code value}, right to left, doubling every second digit (starting with the
45	     * rightmost). Non-digit characters are ignored, so it works directly on a formatted
46	     * {@code customerCode} such as {@code 'NSW-A1B2C3D4'}.
47	     */
48	    default int luhn(String value) {
49	        int sum = 0;
50	        boolean dbl = true;
51	        for (int i = value.length() - 1; i >= 0; i--) {
52	            char c = value.charAt(i);
53	            if (c < '0' || c > '9') {
54	                continue;
55	            }
56	            int d = c - '0';
57	            if (dbl) {
58	                d *= 2;
59	                if (d > 9) {
60	                    d -= 9;
61	                }
62	            }
63	            sum += d;
64	            dbl = !dbl;
65	        }
66	        return (10 - (sum % 10)) % 10;
67	    }
68	
69	    Owner toOwner(OwnerDto ownerDto);
70	
71	    @Mapping(target = "id", ignore = true)
72	    @Mapping(target = "pets", ignore = true)
73	    Owner toOwner(OwnerFieldsDto ownerDto);
74	
75	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
76	
77	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
78	
