453	     * region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
454	     * QLD-&gt;Australia/Brisbane). {@code null} when the region is not in the table.
455	     */
456	    @Transient
457	    public String getTimezone() {
458	        switch (getRegion()) {
459	            case "NSW":
460	                return "Australia/Sydney";
461	            case "VIC":
462	                return "Australia/Melbourne";
463	            case "QLD":
464	                return "Australia/Brisbane";
465	            default:
466	                return null;
467	        }
468	    }
469	
470	    /**
471	     * The owner's preferred contact channel: {@code EMAIL} when an email address is
472	     * present, otherwise {@code PHONE}.
473	     */
474	    @Transient
475	    public String getContactPreference() {
476	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
477	    }
478	
479	    /**
480	     * The owner's derived duplicate-detection key: the SHA-256 hex digest over the
481	     * normalized (E.164) telephone, the lower-cased email (or empty when absent) and the
482	     * Soundex code of the last name, joined by {@code '|'} before hashing. The result is a
483	     * 64-character lower-case hex string. Two owners are duplicates only when their whole
484	     * identity keys are equal; because the telephone is part of the key, two owners with
485	     * the same last name and postcode but different telephones have different keys (and are
486	     * a soft match, not a hard duplicate).
487	     */
488	    @Transient
489	    public String getIdentityKey() {
490	        String tel = this.telephone == null ? "" : this.telephone;
491	        String mail = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
492	        String lastNameCode = Soundex.encode(getLastName());
493	        return sha256hex(tel + "|" + mail + "|" + lastNameCode);
494	    }
495	
496	    /** Lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. */
497	    private static String sha256hex(String value) {
498	        try {
499	            byte[] digest = MessageDigest.getInstance("SHA-256")
500	                    .digest(value.getBytes(StandardCharsets.UTF_8));
501	            StringBuilder sb = new StringBuilder(digest.length * 2);
502	            for (byte b : digest) {
503	                sb.append(String.format("%02x", b));
504	            }
505	            return sb.toString();
506	        }
507	        catch (NoSuchAlgorithmException e) {
508	            throw new IllegalStateException("SHA-256 not available", e);
509	        }
